    assert _drive(f"{_UP}s{_ENTER}", rows=rows) == {"a": "skip_once", "b": "apply"}
    assert _drive(f"{_DOWN}{_DOWN}{_DOWN}s{_ENTER}", rows=rows) == {"a": "apply", "b": "skip_once"}

